<?php
function inflow_history_query(){
 $from=trim((string)($_GET['date_from']??''));$to=trim((string)($_GET['date_to']??''));foreach([$from,$to] as $date)if($date!==''){$d=DateTime::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date)throw new Exception('Enter valid From and To dates.');}if($from!==''&&$to!==''&&$from>$to)throw new Exception('From Date must be on or before To Date.');
 $where=[];$args=[];$q=trim((string)($_GET['inflow_q']??''));if(strlen($q)>200)$q=substr($q,0,200);if($q!==''){$where[]='(b.batch_ref LIKE ? OR b.reference_no LIKE ? OR b.source_name LIKE ? OR b.original_filename LIKE ? OR b.batch_type LIKE ? OR b.status LIKE ? OR b.result_json LIKE ? OR b.error_json LIKE ? OR u.name LIKE ? OR EXISTS(SELECT 1 FROM receipt_staging_lines r LEFT JOIN products p ON p.id=r.product_id WHERE r.batch_id=b.id AND (r.raw_item LIKE ? OR p.name LIKE ? OR p.master_sku LIKE ?)) OR EXISTS(SELECT 1 FROM inflows i JOIN products p ON p.id=i.product_id WHERE i.batch_id=b.id AND (i.reference_no LIKE ? OR p.name LIKE ? OR p.master_sku LIKE ?)))';for($i=0;$i<15;$i++)$args[]='%'.$q.'%';}
 $status=$_GET['inflow_status']??'';if($status==='Awaiting Review'){$where[]="b.status IN ('To Review','Pending Review','Review')";}elseif($status!==''){$where[]='b.status=?';$args[]=$status;}
 foreach(['date_from'=>'>=','date_to'=>'<='] as $field=>$op)if(!empty($_GET[$field])){$d=DateTime::createFromFormat('!Y-m-d',$_GET[$field]);if($d&&$d->format('Y-m-d')===$_GET[$field]){$where[]='b.txn_date'.$op.'?';$args[]=$_GET[$field];}}
 $kind=$_GET['inflow_kind']??'';if($kind!==''){$where[]='b.batch_type=?';$args[]=$kind;}
 if(($_GET['inflow_owner']??'')==='mine'){$where[]='b.user_id=?';$args[]=current_user()['id'];}
 return ['sql'=>' FROM inflow_batches b LEFT JOIN users u ON u.id=b.user_id'.($where?' WHERE '.implode(' AND ',$where):''),'args'=>$args,'query'=>$q];
}
function inflow_search_active(){foreach(['inflow_q','date_from','date_to','inflow_kind','inflow_status','inflow_owner'] as $k)if(trim((string)($_GET[$k]??''))!=='')return true;return ($_GET['inflow_search']??'')==='1';}
function inflow_search_form(){
 echo '<div class="inflow-search-launch"><button type="button" class="btn secondary" data-open-inflow-search aria-haspopup="dialog" aria-controls="inflowSearchDialog"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/></svg> Find Inflow Transactions</button></div><dialog id="inflowSearchDialog" class="inflow-search-dialog" aria-labelledby="inflowSearchTitle"><form method="get" class="modal-card inflow-search-modal">'.(($_GET['inflow_owner']??'')==='mine'?'<input type="hidden" name="inflow_owner" value="mine">':'').'<input type="hidden" name="page" value="inflow"><input type="hidden" name="inflow_search" value="1"><input type="hidden" name="entry" value="'.e(in_array($_GET['entry']??'manual',['manual','bulk','receipt'],true)?($_GET['entry']??'manual'):'manual').'"><div class="modal-head"><div><h3 id="inflowSearchTitle">Find Inflow Transactions</h3><p class="muted">Search receipts, returns and stock entries.</p></div><button type="button" data-close-inflow-search aria-label="Close search">×</button></div><div class="inflow-search-fields"><label class="inflow-search-wide">Search Inflow<input name="inflow_q" value="'.e($_GET['inflow_q']??'').'" placeholder="Receipt, Order ID, product, SKU, supplier, filename, staff, remarks…" maxlength="200"></label><label>From Date<input type="date" name="date_from" value="'.e($_GET['date_from']??'').'"></label><label>To Date<input type="date" name="date_to" value="'.e($_GET['date_to']??'').'"></label><label>Type<select name="inflow_kind"><option value="">All types</option>';foreach(['Receipt PDF','Excel Upload','Order Return','Borrowed Return','Borrowed Issue','Manual'] as $k)echo '<option '.(($_GET['inflow_kind']??'')===$k?'selected':'').'>'.e($k).'</option>';echo '</select></label><label>Status<select name="inflow_status"><option value="">All statuses</option>';foreach(['Awaiting Review','To Review','Confirmed','Cancelled','Unsuccessful','Reversed'] as $s)echo '<option value="'.e($s).'" '.(($_GET['inflow_status']??'')===$s?'selected':'').'>'.e($s==='Confirmed'?'Posted / Confirmed':$s).'</option>';echo '</select></label></div><p class="inflow-search-validation alert danger" hidden></p><div class="inflow-search-footer"><a class="btn ghost" href="?page=inflow">Clear Filters</a><div><button type="button" class="btn ghost" data-close-inflow-search>Cancel</button><button class="btn primary">Search Inflow</button></div></div></form></dialog><script src="assets/inflow_search.js"></script>';
}
function inflow_search_summary($total){
 echo '<div class="inflow-results-summary"><div class="card-head"><div><h3>Inflow Search Results</h3><span class="muted">'.$total.' matching transaction'.($total===1?'':'s').'</span></div><button type="button" class="btn ghost" data-open-inflow-search>Edit Search</button></div><div class="inflow-active-filters">';
 foreach(['inflow_q'=>'Search','date_from'=>'From','date_to'=>'To','inflow_kind'=>'Type','inflow_status'=>'Status','inflow_owner'=>'Uploader'] as $k=>$label){$v=trim((string)($_GET[$k]??''));if($v==='')continue;$params=$_GET;unset($params[$k],$params['offset']);$params['page']='inflow';$params['inflow_search']='1';echo '<a class="inflow-filter-chip" href="?'.e(http_build_query($params)).'" aria-label="'.e('Remove '.$label.' filter').'">'.e($label.': '.($k==='inflow_owner'&&$v==='mine'?'My uploads':$v)).' <span aria-hidden="true">×</span></a>';}
 echo '<a class="inflow-clear-link" href="?page=inflow">Clear Filters</a></div><p class="muted small">Results reflect the filters you applied. Open View to inspect a transaction and its items.</p></div>';
}
function inflow_search_link($offset){$p=$_GET;$p['page']='inflow';if(!inflow_search_active())$p['history']='all';$p['offset']=$offset;return '?'.http_build_query($p);}
function inflow_sync_return_history($id){$b=return_batch($id);$a=return_analysis($b);$meta=['return_batch_id'=>$id,'reference_kind'=>'Return Order','condition'=>'See item conditions','destination'=>'Original Platform / Non-Sellable','rows'=>$a['rows']];$quantity=$b['status']==='Posted'?array_sum(array_column($a['rows'],'qty')):0;$status=['Review'=>'To Review','Posted'=>'Confirmed','Cancelled'=>'Cancelled','Reversed'=>'Reversed'][$b['status']]??$b['status'];$orders=implode(', ',array_unique(array_column($a['rows'],'order')));$candidate=$a['rows'][0]['date']??'';$dateCheck=DateTime::createFromFormat('!Y-m-d',$candidate);$historyDate=$dateCheck&&$dateCheck->format('Y-m-d')===$candidate?$candidate:date('Y-m-d');db()->prepare('INSERT INTO inflow_batches(batch_ref,batch_type,source_name,reference_no,txn_date,attachment_path,original_filename,status,total_qty,error_count,error_json,result_json,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE reference_no=VALUES(reference_no),status=VALUES(status),total_qty=VALUES(total_qty),error_count=VALUES(error_count),error_json=VALUES(error_json),result_json=VALUES(result_json)')->execute([$b['batch_ref'],'Order Return','Order Return',substr($orders,0,100),$historyDate,$b['stored_path'],$b['filename'],$status,$quantity,count($a['errors']),json_encode($a['errors']),json_encode($meta),$b['created_by']]);}
